begin;
create or replace function platform_private.get_notification_push_subscription_state(p_actor_device_id uuid,p_endpoint text) returns jsonb language plpgsql security definer set search_path='' as $$declare ctx jsonb;actor uuid;s platform.notification_push_subscriptions%rowtype;begin ctx:=nullif(pg_catalog.current_setting('platform.phase1c_context',true),'')::jsonb;if ctx is null or ctx->>'purpose'<>'PLATFORM_DEVICE_SESSION_DISPATCH' or (ctx->>'device_id')::uuid is distinct from p_actor_device_id then raise exception 'APPROVED_DEVICE_SESSION_REQUIRED' using errcode='42501';end if;actor:=(ctx->>'user_id')::uuid;if p_endpoint is null or p_endpoint not like 'https://%' or char_length(p_endpoint)>2048 then raise exception 'PLATFORM_NOTIFICATION_SUBSCRIPTION_INVALID' using errcode='22023';end if;select * into s from platform.notification_push_subscriptions where user_id=actor and device_id=p_actor_device_id and endpoint=p_endpoint limit 1;return jsonb_build_object('registered',found,'active',coalesce(s.active,false),'moduleKeys',coalesce(to_jsonb(s.module_keys),'[]'::jsonb),'updatedAt',s.updated_at);end$$;
revoke all on function platform_private.get_notification_push_subscription_state(uuid,text) from public,anon,authenticated,service_role;
do $patch$ declare source_sql text;updated_sql text;needle text;begin source_sql:=pg_get_functiondef('platform.execute_device_operation(uuid,uuid,bytea,text,text,jsonb)'::regprocedure);if position('get_notification_push_subscription_state' in source_sql)>0 then return;end if;needle:='when ''upsert_notification_push_subscription'' then';if position(needle in source_sql)=0 then raise exception 'PLATFORM_NOTIFICATION_PUSH_STATE_DISPATCHER_DRIFT';end if;updated_sql:=replace(source_sql,needle,'when ''get_notification_push_subscription_state'' then -- get_notification_push_subscription_state
perform platform_private.require_exact_jsonb_keys(p_args,array[''p_endpoint'']);return platform_private.get_notification_push_subscription_state(v_session.device_id,p_args->>''p_endpoint'');
'||needle);execute updated_sql;end$patch$;
commit;